WITH enriched AS (SELECT *, AVG(quantity) OVER (ORDER BY unit_price, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) quantity_avg_6, SUM(quantity) OVER w_ordered cumulative_quantity FROM order_items WINDOW w_ordered AS (PARTITION BY product_id, order_id ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT CASE WHEN quantity >= 7 THEN 'LARGE' ELSE 'SMALL' END AS quantity_tier, CASE WHEN quantity_avg_6 >= 9 THEN 'HIGH' ELSE 'LOW' END AS quantity_avg_6_tier, ROUND(AVG(unit_price), 2) AS avg_unit_price, BIT_AND(quantity) AS quantity_bit_and, APPROX_PERCENTILE(quantity, 0.5) AS quantity_p50 FROM enriched GROUP BY quantity_tier, quantity_avg_6_tier ORDER BY quantity_tier DESC
